1	// Final verification tests (testing section): spec edge cases the builder suites do not cover.
2	import { afterEach, describe, test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import fs from 'node:fs';
5	import net from 'node:net';
6	import path from 'node:path';
7	import {
8	  JSON_TYPE, cleanupAll, parseRaw, post, rawGet, rawRequest, request, runToExit, startServer, tmpDir,
9	} from './helpers.mjs';
10	
11	afterEach(cleanupAll);
12	
13	const VALID = Object.freeze({ room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00' });
14	const book = (over = {}) => ({ ...VALID, ...over });
15	const DATE_MSG = 'date must be a valid YYYY-MM-DD date';
16	const NOT_FOUND = { error: 'not found' };
17	const METHOD = { error: 'method not allowed' };
18	const BIG = 2_000_000;
19	
20	function expectError(res, status, message, label = '') {
21	  assert.equal(res.status, status, `${label} status (body ${res.text})`);
22	  assert.equal(res.headers['content-type'], JSON_TYPE, `${label} content-type`);
23	  assert.deepEqual(res.json, { error: message }, label);
24	}
25	
26	async function boot(seed) {
27	  const dir = tmpDir();
28	  const file = path.join(dir, 'b.json');
29	  if (seed !== undefined) fs.writeFileSync(file, seed);
30	  return { ...(await startServer({ env: { DATA_FILE: file } })), file };
31	}
32	
33	const ids = async (port, query = '') => (await request(port, { path: `/api/bookings${query}` })).json.bookings.map((b) => b.id);
34	
35	/** Raw HTTP/1.1 request with an optional body; returns the parsed reply. */
36	async function raw(port, method, target, { body, headers = '' } = {}) {
37	  const buf = body === undefined ? Buffer.alloc(0) : Buffer.from(body);
38	  const length = body === undefined ? '' : `Content-Length: ${buf.length}\r\n`;
39	  const head = `${method} ${target} HTTP/1.1\r\nHost: x\r\nConnection: close\r\n${headers}${length}\r\n`;
40	  return parseRaw(await rawRequest(port, Buffer.concat([Buffer.from(head), buf])));
41	}
42	
43	describe('final: startup', () => {
44	  for (const value of ['1\n2', '\n', '80\r', 'a\r\nb', '٣']) {
45	    test(`PORT=${JSON.stringify(value)} exits 1 with exactly one stderr line`, async () => {
46	      const r = await runToExit({ env: { PORT: value } });
47	      assert.equal(r.code, 1);
48	      assert.equal(r.stdout, '');
49	      assert.match(r.stderr, /^[^\r\n]+\n$/);
50	    });
51	  }
52	
53	  test('a folder on the path that is a file (ENOTDIR) is a read failure, not "no bookings"', async () => {
54	    const dir = tmpDir();
55	    const file = path.join(dir, 'plain');
56	    fs.writeFileSync(file, 'x');
57	    const name = path.join(file, 'b.json');
58	    const r = await runToExit({ env: { DATA_FILE: name } });
59	    assert.deepEqual(r, { code: 1, stdout: '', stderr: `cannot read data file ${name}\n` });
60	  });
61	
62	  test('an absolute DATA_FILE is reported exactly as given', async () => {
63	    const dir = tmpDir();
64	    const name = path.join(dir, 'd.json');
65	    fs.writeFileSync(name, '{}');
66	    const r = await runToExit({ env: { DATA_FILE: name } });
67	    assert.deepEqual(r, { code: 1, stdout: '', stderr: `cannot read data file ${name}\n` });
68	  });
69	
70	  test('startup reads but never rewrites a valid file it did not write itself', async () => {
71	    const text = `{\n  "nextId": 3,\n  "bookings": [${JSON.stringify({ id: 2, ...VALID })}]\n}\n`;
72	    const s = await boot(text);
73	    const before = fs.statSync(s.file).mtimeMs;
74	    assert.deepEqual(await ids(s.port), [2]);
75	    await request(s.port, { path: '/api/rooms' });
76	    assert.equal(fs.readFileSync(s.file, 'utf8'), text);
77	    assert.equal(fs.statSync(s.file).mtimeMs, before);
78	    assert.equal((await post(s.port, book({ date: '2026-11-04' }))).json.id, 3);
79	  });
80	
81	  test('PORT=0 prints the bound port and nothing else', async () => {
82	    const s = await startServer();
83	    assert.equal(s.stdout(), `listening on http://127.0.0.1:${s.port}\n`);
84	    const probe = net.connect(s.port, '127.0.0.1');
85	    await new Promise((resolve, reject) => { probe.once('connect', resolve); probe.once('error', reject); });
86	    probe.destroy();
87	  });
88	});
