90	describe('final: concurrency over raw sockets', () => {
91	  test('30 overlapping bookings written at once: exactly one 201, 29 × 409, one id', async () => {
92	    const s = await boot();
93	    const pad = (n) => String(n).padStart(2, '0');
94	    const bodies = Array.from({ length: 30 }, (_, i) => JSON.stringify(book({ start: `09:${pad(i)}`, end: `10:${pad(i)}` })));
95	    const replies = await Promise.all(bodies.map((body) => raw(s.port, 'POST', '/api/bookings', {
96	      body, headers: 'Content-Type: application/json\r\n',
97	    })));
98	    const created = replies.filter((r) => r.status === 201);
99	    assert.equal(created.length, 1);
100	    assert.equal(replies.filter((r) => r.status === 409).length, 29);
101	    assert.equal(created[0].json.id, 1);
102	    assert.deepEqual(await ids(s.port), [1]);
103	    assert.equal(JSON.parse(fs.readFileSync(s.file, 'utf8')).bookings.length, 1);
104	  });
105	});
