107	describe('final: body draining', () => {
108	  const big = 'x'.repeat(BIG);
109	  test('large bodies on every kind of reply are drained and the reply arrives', async () => {
110	    const s = await boot();
111	    const rooms = await request(s.port, { path: '/api/rooms', headers: { 'Content-Type': 'text/plain' }, body: big });
112	    assert.equal(rooms.status, 200);
113	    expectError(await request(s.port, { method: 'POST', path: '/nope', body: big }), 404, 'not found');
114	    expectError(await request(s.port, { method: 'PUT', path: '/api/rooms', body: big }), 405, 'method not allowed');
115	    expectError(await request(s.port, { method: 'DELETE', path: '/api/bookings/1', body: big }), 404, 'booking not found');
116	    expectError(await request(s.port, { method: 'POST', path: '/api/bookings', body: big }), 415,
117	      'content type must be application/json');
118	    expectError(await request(s.port, {
119	      method: 'POST', path: '/api/bookings', headers: { 'Content-Type': 'application/json' }, body: big,
120	    }), 413, 'body too large');
121	  });
122	});
