124	describe('final: routing', () => {
125	  test('HEAD and OPTIONS on listed paths are 405; asterisk and absolute targets are 404', async () => {
126	    const s = await boot();
127	    for (const target of ['/', '/app.js', '/api/rooms', '/api/bookings', '/api/bookings/1']) {
128	      assert.equal(parseRaw(await rawGet(s.port, target, 'HEAD')).status, 405, `HEAD ${target}`);
129	      const opt = parseRaw(await rawGet(s.port, target, 'OPTIONS'));
130	      assert.equal(opt.status, 405, `OPTIONS ${target}`);
131	      assert.deepEqual(opt.json, METHOD, `OPTIONS ${target}`);
132	    }
133	    for (const [method, target] of [['OPTIONS', '*'], ['GET', 'http://x/api/rooms'], ['GET', '/api/rooms#x']]) {
134	      const res = parseRaw(await rawGet(s.port, target, method));
135	      assert.equal(res.status, 404, `${method} ${target}`);
136	      assert.deepEqual(res.json, NOT_FOUND, `${method} ${target}`);
137	    }
138	  });
139	
140	  test('the id route takes any non-empty id without a slash, and the query is cut off', async () => {
141	    const s = await boot();
142	    await post(s.port, book());
143	    // Node's HTTP parser itself rejects raw non-ASCII bytes in the target, so Arabic-Indic 1 is sent encoded.
144	    for (const id of ['%2F', '%D9%A1', '1;x', '1%3F', '1.']) {
145	      const target = `/api/bookings/${id}`;
146	      const del = await raw(s.port, 'DELETE', target);
147	      assert.equal(del.status, 404, `DELETE ${target}`);
148	      assert.deepEqual(del.json, { error: 'booking not found' }, `DELETE ${target}`);
149	      assert.deepEqual((await raw(s.port, 'GET', target)).json, METHOD, `GET ${target}`);
150	    }
151	    for (const target of ['/api/bookings//', '/api/bookings/%2F/', '/api/bookings/1/?x']) {
152	      assert.deepEqual((await raw(s.port, 'DELETE', target)).json, NOT_FOUND, target);
153	    }
154	    assert.deepEqual((await raw(s.port, 'DELETE', '/api/bookings?x=1')).json, METHOD);
155	    assert.deepEqual((await raw(s.port, 'GET', '/api/bookings/1?date=x')).json, METHOD);
156	    assert.equal((await raw(s.port, 'DELETE', '/api/bookings/1?x=/')).status, 204);
157	    assert.deepEqual(await ids(s.port), []);
158	  });
159	});
