161	describe('final: listing', () => {
162	  async function seeded() {
163	    const s = await boot();
164	    const order = [
165	      ['Cosmos', '2026-11-03', '09:00', '09:30'], ['Aurora', '2026-11-03', '09:00', '09:30'],
166	      ['Borealis', '2026-11-03', '09:00', '09:30'], ['Aurora', '2026-11-02', '23:00', '23:59'],
167	      ['Aurora', '2026-11-03', '08:59', '09:00'], ['Borealis', '2026-11-04', '00:00', '00:30'],
168	    ];
169	    for (const [room, date, start, end] of order) {
170	      assert.equal((await post(s.port, book({ room, date, start, end }))).status, 201, `${room} ${date} ${start}`);
171	    }
172	    return s;
173	  }
174	
175	  test('sorted by date, then start, then room order (not by id or name)', async () => {
176	    const s = await seeded();
177	    assert.deepEqual(await ids(s.port), [4, 5, 2, 3, 1, 6]);
178	  });
179	
180	  test('date filter: first of repeated values, other params ignored, + decodes to space', async () => {
181	    const s = await seeded();
182	    assert.deepEqual(await ids(s.port, '?date=2026-11-03&date=bad'), [5, 2, 3, 1]);
183	    assert.deepEqual(await ids(s.port, '?Date=bad&x'), [4, 5, 2, 3, 1, 6]);
184	    assert.deepEqual(await ids(s.port, '?x=1&date=2026-11-04&date='), [6]);
185	    assert.deepEqual(await ids(s.port, '?date=2026-12-31'), []);
186	    for (const q of ['?date=2026-11-03+', '?date=2026-11-03%20', '?date&date=2026-11-03', '?date=%EF%BC%92026-11-03']) {
187	      expectError(await request(s.port, { path: `/api/bookings${q}` }), 400, DATE_MSG, q);
188	    }
189	  });
190	});
