192	describe('final: booking rules', () => {
193	  test('leap years: every year divisible by 4 in range, including 2000 and 2096', async () => {
194	    const s = await boot();
195	    for (const [i, date] of ['2000-02-29', '2004-02-29', '2096-02-29', '2099-12-31', '2026-12-31'].entries()) {
196	      assert.equal((await post(s.port, book({ date, start: `0${i}:00`, end: `0${i}:30` }))).status, 201, date);
197	    }
198	    for (const date of ['2001-02-29', '2099-02-29', '2000-02-30', '2026-06-31', '1999-02-29', '2100-02-29', '2026-1-01']) {
199	      expectError(await post(s.port, book({ date })), 400, DATE_MSG, date);
200	    }
201	  });
202	
203	  test('inherited keys are not fields, and Unicode whitespace is trimmed from titles', async () => {
204	    const s = await boot();
205	    const proto = '{"__proto__":{"room":"Aurora","title":"T","date":"2026-11-03","start":"09:00","end":"10:00"}}';
206	    const res = await raw(s.port, 'POST', '/api/bookings', { body: proto, headers: 'Content-Type: application/json\r\n' });
207	    assert.equal(res.status, 400);
208	    assert.deepEqual(res.json, { error: 'room must be one of Aurora, Borealis, Cosmos' });
209	    expectError(await post(s.port, book({ title: '　 ﻿' })), 400, 'title must be 1 to 80 characters');
210	    const fw = await post(s.port, book({ start: '０９:00' }));
211	    expectError(fw, 400, 'start must be HH:MM');
212	  });
213	
214	  test('409 names the overlapping booking that starts earliest', async () => {
215	    const s = await boot();
216	    for (const [start, end] of [['11:00', '12:00'], ['09:00', '10:00'], ['10:00', '11:00']]) {
217	      assert.equal((await post(s.port, book({ start, end }))).status, 201);
218	    }
219	    expectError(await post(s.port, book({ start: '09:59', end: '11:01' })), 409, 'room is already booked from 09:00 to 10:00');
220	    expectError(await post(s.port, book({ start: '10:30', end: '23:00' })), 409, 'room is already booked from 10:00 to 11:00');
221	    assert.equal((await post(s.port, book({ start: '12:00', end: '12:01' }))).status, 201);
222	  });
223	});
